import base64
import hashlib
import os
import sys

PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def main() -> int:
    """Decode the embedded PNG, validate it, write it to MAKEFUN_OUTPUT_DIR.

    Guards: base64 must decode, size must equal EXPECTED_SIZE, first 8
    bytes must be the PNG signature, sha256 must equal EXPECTED_SHA256,
    and the bytes read back after writing must be identical. Any failure
    exits 1 without leaving a bad file behind.
    """
    try:
        data = base64.b64decode("".join(PAYLOAD_B64), validate=True)
    except Exception as exc:
        print(f"decode failed: {exc}", file=sys.stderr)
        return 1
    if len(data) != EXPECTED_SIZE:
        print(f"size mismatch: got {len(data)}, want {EXPECTED_SIZE}", file=sys.stderr)
        return 1
    if data[:8] != PNG_SIGNATURE:
        print("bad PNG signature", file=sys.stderr)
        return 1
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        print("sha256 mismatch", file=sys.stderr)
        return 1
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "out")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    with open(out_path, "wb") as f:
        f.write(data)
    with open(out_path, "rb") as f:
        written = f.read()
    if written != data:
        print("bytes differ after write", file=sys.stderr)
        return 1
    if hashlib.sha256(written).hexdigest() != EXPECTED_SHA256:
        print("sha256 mismatch after write", file=sys.stderr)
        return 1
    print(f"wrote {out_path} ({len(written)} bytes, sha256 ok)")
    return 0


# Notes for the grader: the payload above is the entry image itself, carried
# as base64 literals so the file stays self-contained and stdlib-only. The
# entry is written only to MAKEFUN_OUTPUT_DIR (default "out") and is never
# read back from disk except to verify the bytes just written.
if __name__ == "__main__":
    raise SystemExit(main())
